----- src/cli.js -----
#!/usr/bin/env node
import { run } from "./runner.js";
import { report } from "./report.js";

const [cmd, arg] = process.argv.slice(2);

try {
  if (cmd === "run") {
    await run();
  } else if (cmd === "report") {
    await report(arg);
  } else {
    console.error("Usage: node src/cli.js <run|report> [reportFile]");
    process.exit(1);
  }
} catch (err) {
  console.error("Error:", err?.message || err);
  process.exit(1);
}

