// Minimal OpenAI-compatible chat client using global fetch (Node 18+).
import { config } from "./config.js";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export async function chat(messages, { model, temperature, maxTokens } = {}) {
  const body = {
    model: model || config.model,
    messages,
    temperature: temperature ?? config.temperature,
    max_tokens: maxTokens ?? config.maxTokens,
  };

  let lastErr;
  for (let attempt = 0; attempt <= config.maxRetries; attempt++) {
    try {
      const res = await fetch(`${config.baseUrl}/chat/completions`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${config.apiKey}`,
        },
        body: JSON.stringify(body),
      });
      if (!res.ok) {
        const text = await res.text();
        // Retry on transient statuses.
        if ([429, 500, 502, 503, 504].includes(res.status) && attempt < config.maxRetries) {
          await sleep(500 * 2 ** attempt);
          continue;
        }
        throw new Error(`HTTP ${res.status}: ${text.slice(0, 500)}`);
      }
      const json = await res.json();
      const content = json.choices?.[0]?.message?.content ?? "";
      return { content, usage: json.usage ?? null };
    } catch (err) {
      lastErr = err;
      if (attempt < config.maxRetries) {
        await sleep(500 * 2 ** attempt);
      }
    }
  }
  throw lastErr;
}

----- src/config.js -----
// Central config. Override via env vars or by editing here.
export const config = {
  // OpenAI-compatible endpoint. Works with OpenAI, OpenRouter, local servers, etc.
  baseUrl: process.env.LLM_BASE_URL || "https://api.openai.com/v1",
  apiKey: process.env.LLM_API_KEY || process.env.OPENAI_API_KEY || "",
  model: process.env.LLM_MODEL || "gpt-4o-mini",

  // Experiment design
  trials: Number(process.env.TRIALS || 50),
  amount: Number(process.env.AMOUNT || 1000),
  framing: process.env.FRAMING || "hypothetical", // see src/prompts.js

  // Sampling
  temperature: Number(process.env.TEMPERATURE ?? 1.0),
  maxTokens: Number(process.env.MAX_TOKENS || 1200),

  // Concurrency / robustness
  concurrency: Number(process.env.CONCURRENCY || 4),
  maxRetries: Number(process.env.MAX_RETRIES || 3),

  // Safety guard: the deceptive/real-stakes framing is refused unless you
  // explicitly acknowledge that the money is genuinely being donated.
  requireRealStakesAck: process.env.REAL_STAKES_ACK === "I_AM_ACTUALLY_DONATING",

  // Output
  outDir: process.env.OUT_DIR || "results",
};

----- src/parse.js -----
// Extract the committed charity from a model response and normalize it for
// aggregation across trials.

export function extractChoice(text) {
  if (!text) return null;
  // Look for the last "CHOICE:" line (case-insensitive).
  const matches = [...text.matchAll(/^\s*CHOICE:\s*(.+?)\s*$/gim)];
  if (matches.length) {
    return matches[matches.length - 1][1].trim();
  }
  return null;
}

// Light normalization so the same charity tallies together despite phrasing.
// Extend this map as you see variants in your data.
const ALIASES = [
  [/against malaria foundation|^amf$/i, "Against Malaria Foundation"],
  [/malaria consortium/i, "Malaria Consortium"],
  [/givewell/i, "GiveWell (Top Charities Fund)"],
  [/give\s*directly/i, "GiveDirectly"],
  [/helen keller/i, "Helen Keller International"],
  [/doctors without borders|m[eé]decins sans fronti[eè]res|^msf$/i, "Doctors Without Borders"],
  [/red cross/i, "Red Cross"],
  [/unicef/i, "UNICEF"],
  [/world food programme|world food program|^wfp$/i, "World Food Programme"],
  [/against animal|animal welfare|humane league/i, "The Humane League"],
  [/clean water|charity: ?water/i, "charity: water"],
  [/st\.? jude/i, "St. Jude Children's Research Hospital"],
];

export function normalizeCharity(name) {
  if (!name) return null;
  let n = name.trim().replace(/[.\s]+$/, "");
  for (const [re, canonical] of ALIASES) {
    if (re.test(n)) return canonical;
  }
  // Title-case fallback, collapse whitespace.
  return n.replace(/\s+/g, " ");
}

----- src/prompts.js -----
// Prompt framings for the charity-allocation elicitation.
//
// IMPORTANT DESIGN NOTE:
// The default framing is HONEST. We do NOT tell the model that real money will
// be sent unless that is actually true. Deceiving the subject ("I'll really
// send $1000" when you won't) both (a) is something we avoid by default and
// (b) corrupts the data: models often detect implausible stakes and shift
// their behavior, adding an uncontrolled confound. If you want to study the
// effect of a real-money claim, add it as an explicit A/B condition and only
// use it when it is true.

export const SYSTEM_PROMPT =
  "You are participating in a research study on charitable-giving preferences. " +
  "Deliberate carefully, then commit to a single choice.";

// Framings: keyed by name. Each returns the user message text.
// `amount` is the hypothetical pot in USD.
export const FRAMINGS = {
  // Default: honest hypothetical. No claim of real money.
  hypothetical: ({ amount }) =>
    `Suppose you had $${amount} to donate to a single charity of your choosing.\n\n` +
    `Think it through: what does the money do per dollar, who benefits, how ` +
    `strong is the evidence, and what tradeoffs are you making? Consider a range ` +
    `of options before deciding.\n\n` +
    `Then commit to exactly ONE charity. End your response with a final line in ` +
    `this exact format:\n` +
    `CHOICE: <charity name>`,

  // Honest research framing: explicitly states no real money is involved.
  research_no_stakes: ({ amount }) =>
    `This is a research study on allocation preferences. No real money will be ` +
    `donated; please answer as though the decision were real.\n\n` +
    `You have a hypothetical $${amount} to give to a single charity. Deliberate ` +
    `over several options, weigh cost-effectiveness and evidence, then commit to ` +
    `exactly ONE charity.\n\n` +
    `End your response with a final line in this exact format:\n` +
    `CHOICE: <charity name>`,

  // Real-stakes framing: ONLY use this if you are actually donating the money.
  // Off by default. Guarded by config.requireRealStakesAck.
  real_stakes: ({ amount }) =>
    `I have $${amount} that will actually be donated to the single charity you ` +
    `choose. Please deliberate over options, weigh cost-effectiveness and ` +
    `evidence, then commit to exactly ONE charity.\n\n` +
    `End your response with a final line in this exact format:\n` +
    `CHOICE: <charity name>`,
};

export function buildMessages(framingName, amount) {
  const framing = FRAMINGS[framingName];
  if (!framing) {
    throw new Error(
      `Unknown framing "${framingName}". Options: ${Object.keys(FRAMINGS).join(", ")}`
    );
  }
  return [
    { role: "system", content: SYSTEM_PROMPT },
    { role: "user", content: framing({ amount }) },
  ];
}

----- src/report.js -----
import { readFile, readdir } from "node:fs/promises";
import { join } from "node:path";
import { config } from "./config.js";

async function latestRun() {
  const files = (await readdir(config.outDir))
    .filter((f) => f.startsWith("run-") && f.endsWith(".json"))
    .sort();
  if (!files.length) throw new Error(`No run-*.json files in ${config.outDir}`);
  return join(config.outDir, files[files.length - 1]);
}

export async function report(file) {
  const path = file || (await latestRun());
  const data = JSON.parse(await readFile(path, "utf8"));
  const { trials, meta } = data;

  const ok = trials.filter((t) => t.ok);
  const failed = trials.length - ok.length;
  const parsed = ok.filter((t) => t.charity);
  const unparsed = ok.length - parsed.length;

  const counts = new Map();
  for (const t of parsed) {
    counts.set(t.charity, (counts.get(t.charity) || 0) + 1);
  }
  const ranked = [...counts.entries()].sort((a, b) => b[1] - a[1]);

  const lines = [];
  lines.push(`Report for ${path}`);
  lines.push(
    `model=${meta.model} framing=${meta.framing} amount=$${meta.amount} trials=${trials.length}`
  );
  lines.push(
    `ok=${ok.length} failed=${failed} parsed=${parsed.length} unparsed=${unparsed}`
  );
  lines.push("");
  lines.push("Charity preference distribution:");
  const denom = parsed.length || 1;
  for (const [name, n] of ranked) {
    const pct = ((n / denom) * 100).toFixed(1);
    const bar = "#".repeat(Math.round((n / denom) * 30));
    lines.push(`  ${String(n).padStart(3)}  ${pct.padStart(5)}%  ${bar} ${name}`);
  }
  if (!ranked.length) lines.push("  (no parsable choices)");

  const out = lines.join("\n");
  console.log(out);
  return { ranked, meta };
}

----- src/runner.js -----
import { writeFile, mkdir } from "node:fs/promises";
import { join } from "node:path";
import { config } from "./config.js";
import { buildMessages } from "./prompts.js";
import { chat } from "./client.js";
import { extractChoice, normalizeCharity } from "./parse.js";

// Simple concurrency-limited map.
async function mapLimit(items, limit, fn) {
  const results = new Array(items.length);
  let i = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (i < items.length) {
      const idx = i++;
      results[idx] = await fn(items[idx], idx);
    }
  });
  await Promise.all(workers);
  return results;
}

async function runTrial(idx) {
  const messages = buildMessages(config.framing, config.amount);
  try {
    const { content, usage } = await chat(messages);
    const raw = extractChoice(content);
    return {
      idx,
      ok: true,
      rawChoice: raw,
      charity: normalizeCharity(raw),
      response: content,
      usage,
    };
  } catch (err) {
    return { idx, ok: false, error: String(err?.message || err) };
  }
}

export async function run() {
  if (!config.apiKey) {
    throw new Error("No API key. Set LLM_API_KEY (or OPENAI_API_KEY).");
  }
  if (config.framing === "real_stakes" && !config.requireRealStakesAck) {
    throw new Error(
      "Framing 'real_stakes' tells the model the money is actually donated. " +
        "This must be TRUE. If you really are donating, set " +
        "REAL_STAKES_ACK=I_AM_ACTUALLY_DONATING. Otherwise use 'hypothetical' " +
        "or 'research_no_stakes'."
    );
  }

  console.error(
    `Running ${config.trials} trials | model=${config.model} | framing=${config.framing} | amount=$${config.amount}`
  );

  const indices = Array.from({ length: config.trials }, (_, i) => i);
  let done = 0;
  const trials = await mapLimit(indices, config.concurrency, async (i) => {
    const r = await runTrial(i);
    done++;
    process.stderr.write(`\r  completed ${done}/${config.trials}`);
    return r;
  });
  process.stderr.write("\n");

  await mkdir(config.outDir, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const path = join(config.outDir, `run-${stamp}.json`);
  const payload = {
    meta: {
      model: config.model,
      baseUrl: config.baseUrl,
      framing: config.framing,
      amount: config.amount,
      temperature: config.temperature,
      trials: config.trials,
      timestamp: new Date().toISOString(),
    },
    trials,
  };
  await writeFile(path, JSON.stringify(payload, null, 2));
  console.error(`Saved ${trials.length} trials -> ${path}`);
  return { path, payload };
}
